() => {
  // 搜索页面中的关键财务数据
  const financialData = {};

  // 查找股价相关信息
  const priceElements = document.querySelectorAll('[data-name*="price"], [data-name*="Price"], .price, .market-price');
  const marketCapElements = document.querySelectorAll('[data-name*="market"], [data-name*="Market"], .market-cap, .market-cap-value');
  const peElements = document.querySelectorAll('[data-name*="PE"], [data-name*="pe"], .pe-ratio, .pe');
  const volumeElements = document.querySelectorAll('[data-name*="volume"], [data-name*="Volume"], .volume, .trading-volume');

  // 提取数值
  const extractValue = (elements) => {
    const values = [];
    elements.forEach(el => {
      const text = el.textContent || el.innerText;
      if (text) values.push(text.trim());
    });
    return values;
  };

  financialData.price = extractValue(priceElements);
  financialData.marketCap = extractValue(marketCapElements);
  financialData.peRatio = extractValue(peElements);
  financialData.volume = extractValue(volumeElements);

  return financialData;
}

() => {
  // 滚动页面确保数据加载
  window.scrollTo(0, document.body.scrollHeight / 2);

  // 查找包含数字的表格或列表
  const dataTables = document.querySelectorAll('table, .data-table, .financial-data, .summary, .quote-summary');
  const financialStats = {};

  dataTables.forEach((table, index) => {
    const rows = table.querySelectorAll('tr, .row, .data-row');
    rows.forEach(row => {
      const cells = row.querySelectorAll('td, th, .cell, .data-point');
      if (cells.length >= 2) {
        const label = cells[0].textContent?.trim();
        const value = cells[1].textContent?.trim();
        if (label && value && /\d/.test(value)) {
          financialStats[label] = value;
        }
      }
    });
  });

  // 查找所有包含财务指标的元素
  const allText = document.body.textContent || document.body.innerText;
  const lines = allText.split('\n').map(line => line.trim()).filter(line => line && /\d/.test(line));

  return {
    financialStats,
    sampleLines: lines.slice(0, 20) // 前20行包含数字的内容
  };
}

